package dao; import java.sql.*; import java.util.*; import negocio.CategoriaDeportiva; public class CategoriaDeportivaDAOMySQL implements CategoriaDeportivaDAO { private static final String Q="SELECT id,codigo,nombre,nivel_orden,color_hex,activo,fecha_creacion,fecha_actualizacion FROM categorias_deportivas"; public CategoriaDeportiva buscar(Connection c,long id){try(PreparedStatement s=c.prepareStatement(Q+" WHERE id=?")){s.setLong(1,id);try(ResultSet r=s.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw new RuntimeException("No se pudo buscar la categoria deportiva.",e);}} public List<CategoriaDeportiva> listarActivas(Connection c){try(PreparedStatement s=c.prepareStatement(Q+" WHERE activo=TRUE ORDER BY nivel_orden");ResultSet r=s.executeQuery()){List<CategoriaDeportiva>x=new ArrayList<>();while(r.next())x.add(map(r));return x;}catch(SQLException e){throw new RuntimeException("No se pudieron listar las categorias deportivas.",e);}} private CategoriaDeportiva map(ResultSet r)throws SQLException{CategoriaDeportiva x=new CategoriaDeportiva();x.setId(r.getLong(1));x.setCodigo(r.getString(2));x.setNombre(r.getString(3));x.setNivelOrden(r.getInt(4));x.setColorHex(r.getString(5));x.setActivo(r.getBoolean(6));Timestamp a=r.getTimestamp(7),b=r.getTimestamp(8);if(a!=null)x.setFechaCreacion(a.toLocalDateTime());if(b!=null)x.setFechaActualizacion(b.toLocalDateTime());return x;} }
